gJc(){return"\u0628\u0644\u063a \u0627\u0644\u062d\u062f \u0627\u0644\u0623\u0642\u0635\u0649 (2)"},
gJa(){return"\u0625\u0646\u0634\u0627\u0621 \u0627\u0644\u062f\u0639\u0648\u0629"},
gJk(){return"\u0627\u0644\u062f\u0639\u0648\u0629 \u062c\u0627\u0647\u0632\u0629"},
