gJC(){return"\u0623\u062f\u062e\u0644 \u0627\u0644\u0631\u0645\u0632 \u0627\u0644\u0630\u064a \u0623\u064f\u0631\u0633\u0644 \u0625\u0644\u064a\u0643."},
gJA(){return"\u0627\u0644\u0631\u0645\u0632"},
gxP(){return"\u0627\u0644\u062f\u0639\u0648\u0629 \u063a\u064a\u0631 \u0645\u0648\u062c\u0648\u062f\u0629 \u0623\u0648 \u0645\u0646\u062a\u0647\u064a\u0629."},
