JK(a){return"\u0623\u064f\u0631\u0633\u0644\u062a \u0627\u0644\u062f\u0639\u0648\u0629 \u0645\u0646 "+a+" \u0634\u062e\u0635\u064a\u064b\u0627."},
gJN(){return"\u062a\u0633\u0627\u0639\u062f Lyhanna \u0639\u0644\u0649 \u0625\u064a\u062c\u0627\u062f \u0627\u0644\u0645\u0641\u0642\u0648\u062f \u0628\u0633\u0631\u0639\u0629. \u0627\u0644\u0623\u0634\u062e\u0627\u0635 \u0627\u0644\u0645\u0648\u062b\u0648\u0642\u0648\u0646 \u0647\u0645 \u0645\u0646 \u0642\u062f \u064a\u0643\u0648\u0646 \u0627\u0644\u0645\u0641\u0642\u0648\u062f \u0639\u0646\u062f\u0647\u0645\u060c \u0623\u0648 \u0642\u062f \u062a\u0643\u0648\u0646 \u0644\u062f\u064a\u0647\u0645 \u0623\u062e\u0628\u0627\u0631\u0647."},
