gPJ(){return"\u062a\u0639\u0630\u0631 \u0627\u0644\u062a\u062d\u0642\u0642 \u0645\u0646 \u0623\u064a \u0645\u0643\u0627\u0646"},
gPK(){return"\u0645\u063a\u0644\u0642 \u0623\u0648 \u064a\u062a\u0639\u0630\u0631 \u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u064a\u0647 \u0623\u0648 \u0644\u0627 \u0645\u0639\u0644\u0648\u0645\u0627\u062a: \u064a\u0633\u062a\u0645\u0631 \u0627\u0644\u0625\u062c\u0631\u0627\u0621."},
gAl(){return"\u0644\u0645 \u064a\u0643\u0646 \u0627\u0644\u0645\u062d\u0645\u064a \u0647\u0646\u0627\u0643"},
gOZ(){return"\u0645\u062a\u0627\u062d \u0628\u0639\u062f \u0627\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0631\u062f."},
gRo(){return"\u0625\u0631\u0633\u0627\u0644 \u0627\u0644\u0645\u0644\u0641 \u0648\u0627\u0644\u0627\u062a\u0635\u0627\u0644 \u0628\u0627\u0644\u0631\u0642\u0645 17"},
